        var mark = fence[1];
        var lang = (fence[2] || '').toLowerCase();
        var body = [];
        i++;
        while (i < lines.length && !(lines[i].trim().indexOf(mark.charAt(0) === '`' ? '```' : '~~~') === 0 && lines[i].trim().replace(/[`~]/g, '') === '')) {
